def myPow(x: float, n: int) -> float:
    def calc_power(x: float, n: int) -> float:
        if x == 0:
            return 0
        if n == 0:
            return 1

        res = calc_power(x, n // 2)
        res = res * res

        if n % 2 == 1:
            return res * x
        else:
            return res

    ans = calc_power(x, abs(n))

    if n >= 0:
        return ans
    else:
        return 1 / ans

