def uniquePaths(m: int, n: int) -> int:
    i = 0
    j = 0
    dp = [1] + [0] * (n - 1)

    while i < m:
        while j < n:
            if j >= 1:
                dp[j] += dp[j - 1]
            j += 1
        i += 1
        j = 0

    return dp[-1]

