from typing import List

def plusOne(digits: List[int]) -> List[int]:
    i = len(digits) - 1
    carry = 0

    # Check if last digit < 9
    if digits[-1] < 9:
        digits[-1] += 1
        return digits
    else:
        carry = 1
        # Loop through digits from end to start
        while i >= 0 and carry > 0:
            if digits[i] + carry < 10:
                digits[i] = digits[i] + carry
                carry = 0
            else:
                digits[i] = 0
                carry = 1
                i -= 1

        if carry > 0:
            digits.insert(0, 1)

        return digits

