def countPrimes(n: int) -> int:
    if n < 2:
        return 0

    seen = [False] * n
    ans = 0
    num = 2

    while num < n:
        if seen[num] == True:
            num += 1
            continue
        else:
            ans += 1
            mult = num * num
            while mult < n:
                seen[mult] = True
                mult += num
            num += 1

    return ans

def calculate(s: str) -> int:
    num = 0
    ope = '+'
    stack = []
    idx = 0

    while idx < len(s):
        char = s[idx]

        if char.isdigit():
            num = num * 10 + int(char)

        if char in '+-*/' or idx == len(s) - 1:
            if ope == '+':
                stack.append(num)
            elif ope == '-':
                stack.append(-num)
            elif ope == '*':
                stack.append(stack.pop() * num)
            elif ope == '/':
                # int() in Python truncates toward zero for positive/negative results
                stack.append(int(stack.pop() / num))

            ope = s[idx] if s[idx] in '+-*/' else ope
            num = 0

        idx += 1

    result = sum(stack)
