def nthUglyNumber(n):
    Ist = [1]
    seen = {1}
    i = 0
    factors = [2, 3, 5]

    while i < n:
        ugly = Ist.pop(0)

        if i == n - 1:
            return ugly

        f_idx = 0
        while f_idx < len(factors):
            factor = factors[f_idx]
            new = ugly * factor

            if new not in seen:
                seen.add(new)
                Ist.append(new)

            f_idx += 1

        Ist = sorted(Ist)
        i += 1

    return Ist[n - 1]

