from typing import List

def missingNumber(nums: List[int]) -> int:
    n = len(nums)
    v = [-1] * (n + 1)
    i = 0

    for num in nums:
        v[num] = num

    while i < len(v):
        if v[i] == -1:
            return i
        else:
            i += 1

    return 0

