def largestDivisibleSubset(nums: List[int]) -> List[int]:
    nums = sorted(nums)
    n = len(nums)
    i = 0
    j = 0
    ans = []

    if n < 2:
        return nums

    ans = [[num] for num in nums]

    i = 0
    while i < n:
        j = 0
        while j < i:
            if nums[i] % nums[j] == 0 and len(ans[i]) < len(ans[j]) + 1:
                ans[i] = ans[j] + [nums[i]]
            j += 1
        i += 1

    result = max(ans, key=lambda x: len(x))
    return result", "error": null, "messages": []}

