from typing import List

def fizzBuzz(n: int) -> List[str]:
    answer = []
    i = 1
    while i <= n:
        if i % 3 == 0 and i % 5 == 0:
            answer.append('FizzBuzz')
        elif i % 3 == 0:
            answer.append('Fizz')
        elif i % 5 == 0:
            answer.append('Buzz')

        if i % 3 != 0 and i % 5 != 0:
            answer.append(str(i))
        i += 1
    return answer

def numberOfBoomerangs(points):
    ans = 0
    n = len(points)
    i = 0

    while i < n:
        p1 = points[i]
        m = {}
        j = 0

        while j < n:
            p2 = points[j]
            if p1 == p2:
                j += 1
                continue

            d = (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

            if d in m:
                ans += 2 * m[d]

            m[d] = 1 + m.get(d, 0)
            j += 1

        i += 1

    return ans

