def totalHammingDistance(nums: List[int]) -> int:
    ans = 0
    i = 0
    while i < 32:
        zero = 0
        one = 0
        num_idx = 0
        mask = 1 << i
        while num_idx < len(nums):
            if (mask & nums[num_idx]) != 0:
                one += 1
            else:
                zero += 1
            num_idx += 1
        ans += one * zero
        i += 1
    return ans", "error": null, "messages": []}

