def largestPalindrome(n: int) -> int:
    if n == 1:
        return 9

    upper = 10**n - 1
    lower = 10**(n - 1)
    i = upper

    while i >= lower:
        s = str(i)
        pal = int(s + s[::-1])
        j = upper

        while j * j >= pal:
            if pal % j == 0 and len(str(pal // j)) == n:
                return pal % 1337
            j -= 1

        i -= 1

    return -1

