from typing import List

def PredictTheWinner(nums: List[int]) -> bool:
    def calc(i: int, j: int, check: bool) -> int:
        if i > j:
            return 0

        if check:
            # Player 1's turn: maximize score
            best = max(
                calc(i + 1, j, False) + nums[i],
                calc(i, j - 1, False) + nums[j]
            )
        else:
            # Player 2's turn: minimize score (or maximize their own)
            best = min(
                calc(i + 1, j, True) - nums[i],
                calc(i, j - 1, True) - nums[j]
            )
        return best

    result = calc(0, len(nums) - 1, True)
    return result >= 0

