from typing import List
import math

def constructRectangle(area: int) -> List[int]:
    divisor = int(math.pow(area, 0.5))

    while True:
        if area % divisor == 0:
            L = area // divisor
            W = divisor
            if L >= W:
                return [L, W]

        divisor -= 1

