from typing import List

def constructArray(n: int, k: int) -> List[int]:
    ans = list(range(1, n - k + 1))
    i = 0
    while i < k:
        diff = i // 2 + 1
        if i % 2 == 0:
            ans.append(n - diff + 1)
        else:
            ans.append(n - k + diff)
        i += 1
    return ans

