import math

def reachNumber(target: int) -> int:
    target = abs(target)
    n = math.ceil(math.sqrt(2 * target) - 1)

    while True:
        upper = n * (n + 1) // 2
        if upper >= target and (upper - target) % 2 == 0:
            return n
        n = n + 1

