from typing import List

def isIdealPermutation(A: List[int]) -> bool:
    i = 0
    while i < len(A):
        # Check if the current element is more than 1 position away from its index
        # This condition is equivalent to checking if there exists a non-local inversion
        if i - A[i] > 1 or i - A[i] < -1:
            return False
        i += 1
    return True

