def consecutiveNumbersSum(n: int) -> int:
    count = 0
    k = 1

    while k < n:
        x = n / (k + 1) - k / 2

        if x <= 0:
            k = n
            # End loop logic
            break
        else:
            if x == int(x):
                count += 1
                k += 1
            else:
                k += 1

    return count + 1

