def nthMagicalNumber(n: int, a: int, b: int) -> int:
    def gcd(a: int, b: int) -> int:
        if b == 0:
            return a
        return gcd(b, a % b)

    lo = 2
    hi = 10**100
    res = 0

    gcd_ab = gcd(a, b)
    lcm_ab = (a * b) // gcd_ab

    while lo <= hi:
        mid = (lo + hi) // 2
        if (mid // a) + (mid // b) - (mid // lcm_ab) >= n:
            res = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return res % (10**9 + 7)

