def orderlyQueue(s: str, k: int) -> str:
    if k > 1:
        return "".join(sorted(s))
    else:
        m = s
        i = 1
        while i < len(s):
            new_s = s[i:] + s[:i]
            m = min(m, new_s)
            i += 1
