from typing import List
import math
from collections import Counter

def hasGroupsSizeX(deck: List[int]) -> bool:
    def gcd(a: int, b: int) -> int:
        if b == 0:
            return a
        return gcd(b, a % b)

    # Process: Count occurrences of each number
    counts = Counter(deck)

    # Process: Find greatest common divisor (GCD) of all counts
    vals = list(counts.values())
    g = vals[0]
    for v in vals[1:]:
        g = gcd(g, v)

    # Decision: Is GCD >= 2?
    if g >= 2:
        return True
    else:
        return False

