from typing import List

def largestPerimeter(nums: List[int]) -> int:
    nums = sorted(nums, reverse=True)
    i = 0
    while i < len(nums) - 2:
        if nums[i] < nums[i + 1] + nums[i + 2]:
            return nums[i] + nums[i + 1] + nums[i + 2]
        else:
            i += 1
    return 0

