    cell_to_distance = {}

    # Nested loops to populate matrix
    for i in range(rows):
        for j in range(cols):
            matrix.append([i, j])

    # Calculate distances
    for k in range(len(matrix)):
        cell = matrix[k]
        dist = abs(cell[0] - rCenter) + abs(cell[1] - cCenter)
        cell_to_distance[tuple(cell)] = dist

    # Sort keys by distance
    sorted_keys = sorted(cell_to_distance.keys(), key=lambda x: cell_to_distance[x])

    # Update matrix with sorted cells
    matrix = [list(k) for k in sorted_keys]

    return matrix", "error": null, "messages": []}

