def gcdOfStrings(str1, str2):
    while True:
        # Check if concatenation order matters (if they don't share a base)
        if str1 + str2 != str2 + str1:
            return ""

        # If lengths are equal, we found the GCD
        if len(str1) == len(str2):
            return str1

        # Euclidean-like reduction based on length
        if len(str1) > len(str2):
            str1 = str1[len(str2):]
        else:
            str2 = str2[len(str1):]

