def distributeCandies(c, n):
    a = [0] * n
    s = 0
    ga = 0

    while True:
        if s == n:
            s = 0

        if c - (ga + 1) >= 0:
            ga += 1
            a[s] += ga
            c -= ga
            s += 1
        else:
            a[s] += c
            return a

