from typing import List

def numIdenticalPairs(nums: List[int]) -> int:
    count = 0
    i = 0
    while i < len(nums):
        j = i + 1
        while j < len(nums):
            if nums[i] == nums[j]:
                count += 1
            j += 1
        i += 1
    return count

