def abbreviateProduct(left: int, right: int) -> str:
    c2 = 0
    c5 = 0
    top12 = 1
    tail5 = 1
    i = left

    while i <= right:
        temp_i = i
        while temp_i % 2 == 0:
            c2 += 1
            temp_i //= 2
        while temp_i % 5 == 0:
            c5 += 1
            temp_i //= 5

        top12 = int(str(top12 * temp_i)[:12])
        tail5 = (tail5 * temp_i) % 100000
        i += 1

    while c2 > c5:
        top12 = int(str(top12 * 2)[:12])
        tail5 = (tail5 * 2) % 100000
        c2 -= 1

    while c5 > c2:
        top12 = int(str(top12 * 5)[:12])
        tail5 = (tail5 * 5) % 100000
        c5 -= 1

    zero = min(c2, c5)

    if len(str(top12)) <= 10:
        return str(top12) + 'e' + str(zero)
    else:
        s_tail = str(tail5)
        return str(top12)[:5] + '...' + '0' * (5 - len(s_tail)) + s_tail + 'e' + str(zero)

