import math

def replaceNonCoprimes(a, b):
    while b:
        a, b = b, a % b
    return a

def replaceNonCoprimes(A):
    res = []
    for a in A:
        # The logic in the ILR uses a while loop to repeatedly merge 
        # the current element 'a' with the last element in 'res' 
        # if they are non-coprime (gcd > 1).
        while True:
            x = gcd(res[-1] if res else 1, a)
            if x == 1:
                res.append(a)
                break
            else:
                # LCM(a, b) = (a * b) // GCD(a, b)
                # Here we replace the last element and 'a' with their LCM
                last = res.pop()
                a = (a * last) // x
    return res

