def divisorSubstrings(num: int, k: int) -> int:
    s = str(num)
    b = 0
    i = 0

    while i < len(s) - k + 1:
        x = int(s[i : i + k])
        if x != 0 and num % x == 0:
            b += 1
        i += 1

    return b

