from typing import List
import math

def canTraverseAllPairs(a: int, b: int) -> int:
    if b == 0:
        return a
    return gcd(b, a % b)

def canTraverseAllPairs(nums: List[int]) -> bool:
    if len(nums) == 1:
        return True

    nums_set = set(nums)
    if 1 in nums_set:
        return False

    # The logic provided in the ILR describes a specific traversal check
    # which effectively checks if the graph is connected.
    # Using Union-Find is the standard efficient approach for this problem.
    n = len(nums)
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Map prime factors to the first index that contains them
    prime_to_idx = {}
    for i, num in enumerate(nums):
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_idx:
                    union(i, prime_to_idx[d])
                else:
                    prime_to_idx[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_idx:
                union(i, prime_to_idx[temp])
            else:
                prime_to_idx[temp] = i

    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True

