from typing import List
from itertools import accumulate

def maxIncreasingGroups(usageLimits: List[int]) -> int:
    usageLimits.sort()
    n = len(usageLimits)

    def poss(groups, usageLimits, n):
        sub = [usageLimits[0]]
        for i in range(1, n):
            sub.append(usageLimits[i] - usageLimits[i - 1])

        # Decrement sub[i] for the last 'groups' elements
        for i in range(-groups, 0, 1):
            sub[i] -= 1

        acc = list(accumulate(accumulate(sub)))
        for val in acc:
            if val < 0:
                return False
        return True

    l = 0
    r = n
    while l < r:
        mid = (l + r + 1) // 2
        if poss(mid, usageLimits, n):
            l = mid
        else:
            r = mid - 1

    return l

