def beautifulSubstrings(s: str, k: int) -> int:
    p = 0
    i = 1
    while i <= k:
        if (i * i) % k == 0:
            p = i
            i = k + 1
        else:
            i += 1

    p = 2 * p
    sumdict = {0: {p - 1: 1}}
    cursum = 0
    vowels = {'a', 'e', 'i', 'o', 'u'}
    count = 0
    i = 0

    while i < len(s):
        if s[i] in vowels:
            cursum += 1
        else:
            cursum -= 1

        cate = i % p

        if cursum in sumdict:
            if cate in sumdict[cursum]:
                count += sumdict[cursum][cate]
                sumdict[cursum][cate] += 1
            else:
                sumdict[cursum][cate] = 1
        else:
            sumdict[cursum] = {cate: 1}

        i += 1

    return count

import math
from typing import List

def findKthSmallest(coins: List[int], k: int) -> int:
    def check(x: int, coins: List[int], n: int, k: int) -> bool:
        count = 0
        for mask in range(1 << n):
            cnt = 0
            lcm_val = 1
            c = []
            for i in range(n):
                if (mask >> i) & 1:
                    cnt += 1
                    val = coins[i]
                    c.append(val)
                    lcm_val = (lcm_val * val) // math.gcd(lcm_val, val)

            if cnt > 0:
                if cnt & 1:
                    count += x // lcm_val
                else:
                    count -= x // lcm_val
        return count >= k

    l = 0
    r = 10**18
    n = len(coins)

    while l + 1 < r:
        m = (l + r) >> 1
        if check(m, coins, n, k):
            r = m
        else:
            l = m

    return r

from typing import List

def countOfPairs(nums: List[int]) -> int:
    n = len(nums)
    i = n - 1
    dp = [[0 for _ in range(51)] for _ in range(n + 1)]
    dp[n] = [1] * 51

    while i >= 0:
        diff = 0
        if i > 0:
            diff = max(0, nums[i] - nums[i - 1])
        else:
            diff = 0

        j = 50
        while j >= 0:
            # Logic for dp[i][j] = dp[i][j+1]
            if j + 1 <= 50:
                dp[i][j] = dp[i][j + 1]
            else:
                pass

            # Logic for adding dp[i+1][j+diff]
            if j + diff <= nums[i]:
                dp[i][j] = (dp[i][j] + dp[i + 1][j + diff]) % 1_000_000_007
            else:
                pass

            j -= 1

        i -= 1

    return dp[0][0]
